import type { Metadata } from "next";
import { profile } from "@/data/profile";

/**
 * The preview card generated by `app/opengraph-image.tsx`. Listed explicitly
 * because a page that sets its own `openGraph` does not inherit the image
 * from the root segment.
 */
const previewImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${profile.name}, ${profile.title}`,
};

/**
 * Metadata for one page: title, description, canonical URL and the matching
 * Open Graph / Twitter tags, so shared links show the right page title.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: profile.name,
      locale: "en_AU",
      url: path,
      title,
      description,
      images: [previewImage],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [previewImage],
    },
  };
}
